package store

import (
	"fmt"
	"time"

	"github.com/galileostudio/baleia/internal/persistence/partitioning"
	"github.com/galileostudio/baleia/internal/store/model"
	"github.com/google/uuid"
	"gorm.io/gorm"
	"gorm.io/gorm/clause"
	"gorm.io/gorm/schema"
)

// Models is the authoritative store schema (ADR 0020): one GORM model per
// table, with tags and associations.
func Models() []any { return model.All() }

// AutoMigrate creates or reconciles the schema for models. The models declare
// portable column types, defaults and constraints; IDs are generated by the
// application, so no dialect-specific default is needed.
func AutoMigrate(db *gorm.DB, models ...any) error {
	if err := db.AutoMigrate(models...); err != nil {
		return err
	}
	return createForeignKeys(db, models)
}

// createForeignKeys adds the belongs-to constraints once every table exists.
// AutoMigrate runs with DisableForeignKeyConstraintWhenMigrating, because GORM
// otherwise inlines a constraint whose referenced table may not exist yet.
func createForeignKeys(db *gorm.DB, models []any) error {
	for _, m := range models {
		stmt := &gorm.Statement{DB: db}
		if err := stmt.Parse(m); err != nil {
			return err
		}
		for name, rel := range stmt.Schema.Relationships.Relations {
			if rel.Type != schema.BelongsTo {
				continue
			}
			// Engines that forbid foreign keys on partitioned tables keep
			// integrity in the application for these (ADR 0024).
			if !partitioning.CapabilitiesFor(db).ForeignKeysOnPartitioned &&
				touchesPartitioned(stmt.Schema.Table, rel.FieldSchema.Table) {
				continue
			}
			if db.Migrator().HasConstraint(m, name) {
				continue
			}
			if err := db.Migrator().CreateConstraint(m, name); err != nil {
				return fmt.Errorf("create foreign key %s on %T: %w", name, m, err)
			}
		}
	}
	return nil
}

// AllMigrations is the versioned schema registry. Additive transitions call
// AutoMigrate over Models; destructive or renaming transitions use GORM's
// Migrator inside their own versioned entry.
func AllMigrations() (*Registry, error) {
	return NewRegistry(
		Migration{
			Version: 1,
			Name:    "create store schema",
			Up: func(db *gorm.DB) error {
				return AutoMigrate(db, Models()...)
			},
		},
		Migration{
			Version: 2,
			Name:    "create setup locks",
			Up: func(db *gorm.DB) error {
				return AutoMigrate(db, &model.SetupLock{})
			},
		},
		Migration{
			Version: 3,
			Name:    "add metadata sync heartbeat",
			Up: func(db *gorm.DB) error {
				return AutoMigrate(db, &model.MetadataSyncRun{})
			},
		},
		Migration{
			Version: 4,
			Name:    "seed store defaults",
			Up:      seedDefaults,
		},
		Migration{
			Version: 5,
			Name:    "add connection access mode",
			Up: func(db *gorm.DB) error {
				return AutoMigrate(db, &model.CatalogConnection{})
			},
		},
		Migration{
			Version: 6,
			Name:    "expand connection type check",
			Up: func(db *gorm.DB) error {
				// GORM owns the constraint: drop and recreate it from the
				// portable model tag. The MySQL driver maps it to DROP CHECK.
				// A transaction keeps the drop and create together where the
				// backend has transactional DDL (PostgreSQL); MySQL/MariaDB
				// commit DDL per statement, so a failed create leaves the ledger
				// dirty and an operator reconciles it.
				const name = "catalog_connections_type_check"
				return db.Transaction(func(tx *gorm.DB) error {
					if tx.Migrator().HasConstraint(&model.CatalogConnection{}, name) {
						if err := tx.Migrator().DropConstraint(&model.CatalogConnection{}, name); err != nil {
							return fmt.Errorf("drop connection type check: %w", err)
						}
					}
					if err := tx.Migrator().CreateConstraint(&model.CatalogConnection{}, name); err != nil {
						return fmt.Errorf("create connection type check: %w", err)
					}
					return nil
				})
			},
		},
		Migration{
			Version: 7,
			Name:    "create monitoring outbox",
			Up: func(db *gorm.DB) error {
				return AutoMigrate(db, &model.MonitoringEvent{})
			},
		},
		Migration{
			Version: 8,
			Name:    "backfill connection access mode",
			Up:      backfillAccessMode,
		},
		Migration{
			Version: 9,
			Name:    "create webhook tables",
			Up: func(db *gorm.DB) error {
				return AutoMigrate(db, &model.Webhook{}, &model.WebhookDelivery{})
			},
		},
		Migration{
			Version: 10,
			Name:    "add workspace-bound bi keys",
			Up: func(db *gorm.DB) error {
				if err := AutoMigrate(db, &model.APIKey{}); err != nil {
					return err
				}
				return createForeignKeys(db, []any{&model.APIKey{}})
			},
		},
		Migration{
			Version: 11,
			Name:    "add bi gateway executions and switches",
			Up: func(db *gorm.DB) error {
				if err := AutoMigrate(db, &model.QueryExecution{}, &model.Workspace{}, &model.BIGatewaySetting{}); err != nil {
					return err
				}
				if err := createForeignKeys(db, []any{&model.QueryExecution{}}); err != nil {
					return err
				}
				return db.Clauses(clause.OnConflict{DoNothing: true}).
					Create(&model.BIGatewaySetting{ID: true, Enabled: true, UpdatedAt: time.Now().UTC()}).Error
			},
		},
		Migration{
			// The index starts empty: each scope is built on its first
			// search or metadata sync (ADR 0023).
			Version: 12,
			Name:    "create search index",
			Up: func(db *gorm.DB) error {
				return AutoMigrate(db, &model.SearchScope{}, &model.SearchTerm{})
			},
		},
		Migration{
			Version: 13,
			Name:    "create search glossary",
			Up: func(db *gorm.DB) error {
				if err := AutoMigrate(db, &model.SearchSynonym{}); err != nil {
					return err
				}
				return createForeignKeys(db, []any{&model.SearchSynonym{}})
			},
		},
		Migration{
			Version: 14,
			Name:    "partition audit and query history",
			Up:      repartitionQueryHistory,
		},
		Migration{
			Version: 15,
			Name:    "key the export cursor by stream and sink",
			Up:      keyExportCursor,
		},
		Migration{
			Version: 16,
			Name:    "add a cursor key for uuid-keyed streams",
			Up: func(db *gorm.DB) error {
				// query_history is ordered by (started_at, id uuid), so its
				// cursor needs a string tiebreaker next to audit's bigint id.
				return AutoMigrate(db, &model.AuditExportCursor{})
			},
		},
	)
}

// backfillAccessMode sets access_mode on single-path connections (ADR 0021
// CR-17): a connection with a direct engine and no catalogs is direct, and one
// with catalogs and no direct engine is trino. Dual-path connections stay NULL
// until bootstrap.SplitDualPathConnections splits them; engine-family and
// unused connections have no data access mode.
func backfillAccessMode(db *gorm.DB) error {
	var rows []model.CatalogConnection
	if err := db.Where("access_mode IS NULL").Find(&rows).Error; err != nil {
		return fmt.Errorf("list connections to backfill: %w", err)
	}
	for _, c := range rows {
		var direct, trino int64
		if err := db.Model(&model.Engine{}).
			Where("connection_id = ? AND class = 'direct'", c.ID).Count(&direct).Error; err != nil {
			return fmt.Errorf("count direct engines of %s: %w", c.ID, err)
		}
		if err := db.Model(&model.Catalog{}).
			Where("connection_id = ? AND origin = 'source'", c.ID).Count(&trino).Error; err != nil {
			return fmt.Errorf("count catalogs of %s: %w", c.ID, err)
		}
		mode := ""
		switch {
		case direct > 0 && trino == 0:
			mode = "direct"
		case direct == 0 && trino > 0:
			mode = "trino"
		}
		if mode == "" {
			continue
		}
		if err := db.Model(&model.CatalogConnection{}).
			Where("id = ?", c.ID).Update("access_mode", mode).Error; err != nil {
			return fmt.Errorf("set access mode of %s: %w", c.ID, err)
		}
	}
	return nil
}

// seedDefaults creates the rows a fresh database used to seed: the
// default Trino cluster and its federated engine, and the assistant settings
// singleton. Existing rows are left untouched, so the migration is safe on an
// adopted database.
func seedDefaults(db *gorm.DB) error {
	now := time.Now().UTC()
	cluster := model.TrinoCluster{
		ID:             model.UUID(uuid.NewString()),
		Name:           model.Text("default"),
		CoordinatorURL: "http://trino:8080",
		CreatedAt:      now,
	}
	if err := db.Clauses(clause.OnConflict{DoNothing: true}).Create(&cluster).Error; err != nil {
		return fmt.Errorf("seed default trino cluster: %w", err)
	}
	if err := db.Where("name = ?", "default").First(&cluster).Error; err != nil {
		return fmt.Errorf("read default trino cluster: %w", err)
	}
	if cluster.EngineID == nil {
		conn := model.CatalogConnection{
			ID:        model.UUID(uuid.NewString()),
			Name:      model.Text("trino-default"),
			Type:      "trino",
			URL:       "http://trino:8080",
			Config:    model.JSON(`{"url":"http://trino:8080"}`),
			CreatedAt: now,
			UpdatedAt: now,
		}
		if err := db.Clauses(clause.OnConflict{DoNothing: true}).Create(&conn).Error; err != nil {
			return fmt.Errorf("seed trino connection: %w", err)
		}
		if err := db.Where("name = ?", "trino-default").First(&conn).Error; err != nil {
			return fmt.Errorf("read trino connection: %w", err)
		}
		engine := model.Engine{
			ID:           model.UUID(uuid.NewString()),
			Name:         model.Text("default"),
			Kind:         "trino",
			Class:        "federated",
			ConnectionID: conn.ID,
			IdentityMode: model.Text("impersonation"),
			Enabled:      true,
			CreatedAt:    now,
			UpdatedAt:    now,
		}
		if err := db.Clauses(clause.OnConflict{DoNothing: true}).Create(&engine).Error; err != nil {
			return fmt.Errorf("seed trino engine: %w", err)
		}
		if err := db.Where("name = ?", "default").First(&engine).Error; err != nil {
			return fmt.Errorf("read trino engine: %w", err)
		}
		if err := db.Model(&model.TrinoCluster{}).Where("id = ?", string(cluster.ID)).
			Update("engine_id", engine.ID).Error; err != nil {
			return fmt.Errorf("link default trino engine: %w", err)
		}
	}
	settings := model.AssistantSetting{ID: true}
	if err := db.Clauses(clause.OnConflict{DoNothing: true}).Create(&settings).Error; err != nil {
		return fmt.Errorf("seed assistant settings: %w", err)
	}
	return nil
}
